// Match each expected transport diagnostic to the exact fixture response or abort that produced it.
function unexpectedDiagnostics(audits){
 const unexpected=[];
 for(const audit of audits){
  const available=(audit.requests||[]).filter(e=>e.status>=400||e.expectedAbort).map(e=>({...e}));
  for(const message of audit.console||[]){
   const url=message.location?.url;let path;
   try{path=new URL(url).pathname;}catch{unexpected.push(message);continue;}
   const http=message.text.match(/^Failed to load resource: the server responded with a status of (\d{3}) \([^)]+\)$/);
   const status=http?Number(http[1]):null;
   const index=available.findIndex(e=>e.path===path && (status?e.status===status
       && ['BOUNDARY_REQUEST_NOT_FOUND','BOUNDARY_ZONE_PLACE_NOT_SAVED','BOUNDARY_REQUEST_CONFLICT','BOUNDARY_ZONE_PLACE_LOCATION_REQUIRED','BOUNDARY_ZONE_MAP_UNAVAILABLE','BOUNDARY_JOB_CONFLICT'].includes(e.outcome?.code)
        || e.path===path && e.status===status && (
            (/^\/api\/my-maps\/101\/print-annotations$/.test(path)&&[409,503].includes(status)) ||
            (path==='/api/boundary-zone-jobs/402/rows/shared-row/source'&&status===503))
       : e.expectedAbort && message.text==='Failed to load resource: net::ERR_FAILED'));
   if(message.type!=='error'||index<0)unexpected.push(message);
   else available.splice(index,1);
  }
 }
 return unexpected;
}
